import{_ as l,l as n,o as e,c as o,v as t,p as d,x as r,d as p,i as s,S as h}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"薄膜干涉","description":"","frontmatter":{"title":"薄膜干涉","date":"2026-09-10T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/thin-film-interference.md","filePath":"litho/thin-film-interference.md","lastUpdated":1789023840000}'),c={name:"litho/thin-film-interference.md"};function _(m,a,f,E,A,B){const i=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="薄膜干涉" tabindex="-1">薄膜干涉 <a class="header-anchor" href="#薄膜干涉" aria-label="Permalink to &quot;薄膜干涉&quot;">​</a></h1><div class="epigraph"><p>薄层上下界面各反射一束；两束或多束相干叠加，反射率随厚度与波长振荡，单界面菲涅尔公式不够用。</p><footer>—— 据 Born &amp; Wolf, Principles of Optics 第 1.6 节对多层膜与干涉条件的整理</footer></div><p><a href="/litho/brewster-tir">上一课</a>处理了半无限界面上的特殊角。本课不重写 \\(r_p=0\\)。缺口是：介质若有有限厚度 \\(d\\)，上下界面各反射一次（以及多次内反射），这些束如何干涉？后课抗反射层、胶层驻波与多层反射镜，都用这套相位差语言。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/fresnel-coefficients">菲涅尔反射与透射</a> 只给出单个界面。实际膜有厚度：上表面反射与下表面反射走不同光程，往返相位差含 \\(2 n k_0 d\\cos\\theta_t\\)。没有这条差，无法设计「某一波长增透」或「某一波长高反」，也无法解释为什么同一衬底上改胶厚会改反射率。缺口是把两套菲涅尔系数用传播相位连起来，不是再引入一种新的偏振。</p><p>本课是「从麦克斯韦到平面波」这一课序的最后一课。下一课转入几何成像：<a href="/litho/thin-lens-equation">薄透镜成像方程</a>。薄膜公式仍是波动；透镜方程是短波极限。两者都要用，但不要混成一个式子。</p><h3 id="半波损失不是可选项" tabindex="-1">半波损失不是可选项 <a class="header-anchor" href="#半波损失不是可选项" aria-label="Permalink to &quot;半波损失不是可选项&quot;">​</a></h3><p>从低 \\(n\\) 射向高 \\(n\\) 时 \\(r\\lt 0\\)，等价额外 \\(\\pi\\) 相位。只算几何光程 \\(2nd\\)、忘掉界面符号，增透条件会差四分之一波。空气–膜–玻璃与空气–膜–空气的「亮暗」口诀不同，原因正在这里，不是膜的色散。</p><p><span class="marginnote">正入射时往返相位 \\(2 n k_0 d\\)。斜入射把 \\(d\\) 换成 \\(d/\\cos\\theta_t\\) 并改用该角的菲涅尔系数。s 与 p 振荡周期可以错开，矢量膜系必须分开算。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>正入射、单层膜夹在介质 0 与 2 之间，反射振幅的连分式（Airy 求和）给出</p> \\[R=\\left|\\frac{r_{01}+r_{12}e^{i2nkd}}{1+r_{01}r_{12}e^{i2nkd}}\\right|^2, \\]<p>其中 \\(k=k_0 n\\)，\\(r_{01}\\)、\\(r_{12}\\) 为两界面系数。构造性或相消取决于 \\(2nd/\\lambda\\) 与界面相位。四分之一波膜：\\(d\\approx\\lambda/(4n)\\)，若两反射振幅接近且符号相反，则增透。四分之一波高低折射率交替堆叠，则在设计波长附近高反——EUV 掩模 Blank 上的 Mo/Si 多层是同一原理的深 Bragg 栈，传输矩阵是后课工具，本课只建立双光束直觉。</p><p>分母里的 \\(r_{01}r_{12}e^{i2nkd}\\) 是多次内反射。膜很弱时（\\(|r|\\) 小）可只留两束；金属或高反堆栈必须保留多光束。光刻胶–硅腔通常反射不弱，驻波要用完整式而不是「只加两束」。本课公式已经包含这一点，后课驻波只是换名字。</p>',14)),(e(),d(h,null,{default:r(()=>[s(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20IF1%5B%22%E4%B8%8A%E7%95%8C%E9%9D%A2%E5%8F%8D%E5%B0%84%22%5D%20--%3E%20SUM%5B%22%E7%9B%B8%E5%B9%B2%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20IF2%5B%22%E4%B8%8B%E7%95%8C%E9%9D%A2%E5%8F%8D%E5%B0%84%22%5D%20--%3E%20SUM%0A%20%20SUM%20--%3E%20R%5B%22R%20%E9%9A%8F%20%CE%BB%20%E4%B8%8E%20d%20%E6%8C%AF%E8%8D%A1%22%5D%0A%20%20R%20--%3E%20AR%5B%22%E5%A2%9E%E9%80%8F%E6%88%96%E9%AB%98%E5%8F%8D%E8%AE%BE%E8%AE%A1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>薄膜把「路径差 → 相位差 → 强度振荡」写成可算的 \\(R(d,\\lambda)\\)。晶圆上抗蚀剂与衬底形成腔，入射与衬底反射叠加，曝光剂量沿深度起伏——后课称驻波，用底部抗反射层压衬底反射。本课只说明物理是薄膜干涉，不把光刻胶化学提前讲完。</p><p>带宽有限时，不同 \\(\\lambda\\) 的条纹错开，对比度下降，与后课 <a href="/litho/coherence-length-prep">相干长度与光源带宽预备</a> 相连。吸收膜用复 \\(n\\)，振荡被阻尼；EUV 多层必须在吸收与反射率之间折中，仍是本课相位差，只是层数多。</p><p>驻波的纵向周期约 \\(\\lambda/(2n)\\)，胶厚若跨过若干周期，曝光剂量沿深度起伏，侧壁会出波浪。抗反射层把衬底反射压下去，等于把 \\(r_{12}\\) 变小，公式里振荡项变弱。本课点到这一应用就停：不写胶的化学显影，也不把 BARC 工艺参数表搬进来。几何成像从下一课开始，暂时离开膜腔。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不展开传输矩阵软件与膜厚公差优化。粗糙度引起的散射、非均匀膜，不在本课。也不把 \\(R(\\lambda)\\) 写成分辨率判据。下一课改用物距、像距与焦距，暂时不写膜。</p><p>后课默认：提到增透、高反、胶层反射振荡，都先问 \\(2nkd\\) 与菲涅尔相位。几何成像课序从薄透镜方程开始，不再从麦克斯韦重推。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>薄膜是多界面反射的相干叠加；相位差含 \\(2nkd\\) 与界面符号。</li><li>增透与高反由厚度和折射率设计；多层 Bragg 栈是同一原理。</li><li>胶层驻波与抗反射层是后课应用，机制已在本课。</li><li>下一课转入几何成像，不把干涉公式带进透镜方程。</li><li>出处：Born &amp; Wolf, <em>Principles of Optics</em>；Hecht, <em>Optics</em> 第 9 章。</li></ul>',9))])}const k=l(c,[["render",_]]);export{b as __pageData,k as default};
